UPDATE questions SET explanation='姚燧号牧庵，元代著名古文家，其文风刚健宏肆，与虞集并称。选项A、B、C分别指诗、散曲、书画，均非其文学成就核心，故排除。', options='{"A": "以诗名世", "B": "长于散曲", "C": "兼擅书画", "D": "号牧庵为元代古文大家"}' WHERE id=620093;
